import{c as a,Q as e,j as l,m as s}from"./chunks/framework.DOi4mjdC.js";const c=JSON.parse('{"title":"IterateAll","description":"","frontmatter":{},"headers":[{"level":1,"title":"IterateAll","slug":"iterateall"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/IterateAll.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/IterateAll.md"}'),n={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/IterateAll.md"};function r(i,t,d,o,A,p){return e(),l("div",null,[...t[0]||(t[0]=[s(`<h1 id="iterateall" tabindex="-1">IterateAll <a class="header-anchor" href="#iterateall" aria-label="Permalink to &quot;IterateAll&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>调用一次IterateAll，会计算出singleCoreM * singleCoreN大小的C矩阵。迭代顺序可通过tiling参数iterateOrder调整。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool sync = true&gt; __aicore__ inline void IterateAll(const GlobalTensor&lt;DstT&gt;&amp; gm, uint8_t enAtomic = 0, bool enSequentialWrite = false, bool waitIterateAll = false, bool fakeMsg = false)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool sync = true&gt; __aicore__ inline void IterateAll(const LocalTensor&lt;DstT&gt;&amp; ubCmatrix, uint8_t enAtomic = 0)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>sync</td><td>获取C矩阵过程分为同步和异步两种模式： 同步：需要同步等待IterateAll执行结束异步：不需要同步等待IterateAll执行结束 通过该参数设置同步或者异步模式：同步模式设置为true；异步模式设置为false，默认为同步模式。 Atlas 200I/500 A2 推理产品只支持设置为true。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>gm</td><td>输出</td><td>C矩阵。类型为GlobalTensor。 Ascend 950PR/Ascend 950DT，支持的数据类型为：half/float/bfloat16_t/int32_t/int8_t/fp8_e4m3fn_t/hifloat8_t Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：half/float/bfloat16_t/int32_t/int8_t Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：half/float/bfloat16_t/int32_t/int8_t Atlas 推理系列产品AI Core，支持的数据类型为：half/float/int8_t/int32_t Atlas 200I/500 A2 推理产品，支持的数据类型为half/float/bfloat16_t/int32_t Kirin X90，支持的数据类型位：half/int8_t/int32_t</td></tr><tr><td>ubCmatrix</td><td>输出</td><td>C矩阵。类型为LocalTensor，支持的TPosition为TSCM、VECIN，输出到VECIN Tensor时建议使用Iterate接口。 Ascend 950PR/Ascend 950DT，支持的数据类型为：half/float/bfloat16_t/int32_t/int8_t/fp8_e4m3fn_t/hifloat8_t Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：half/float/bfloat16_t/int32_t/int8_t Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：half/float/bfloat16_t/int32_t/int8_t Atlas 推理系列产品AI Core不支持包含该参数的原型接口 Atlas 200I/500 A2 推理产品，支持的数据类型为half/float/bfloat16_t/int32_t Kirin X90，支持的数据类型位：half/int8_t/int32_t</td></tr><tr><td>enAtomic</td><td>输入</td><td>是否开启Atomic操作，默认值为0。 参数取值： 0：不开启Atomic操作 1：开启AtomicAdd累加操作 2：开启AtomicMax求最大值操作 3：开启AtomicMin求最小值操作 对于Atlas 推理系列产品AI Core，只有输出位置是GM才支持开启Atomic操作。 对于Atlas 200I/500 A2 推理产品，只有输出位置是GM才支持开启Atomic操作。</td></tr><tr><td>enSequentialWrite</td><td>输入</td><td>是否开启连续写模式（连续写，写入[baseM, baseN]；非连续写，写入[singleCoreM, singleCoreN]中对应的位置），默认值false（非连续写模式）。 Atlas 200I/500 A2 推理产品不支持该参数。</td></tr><tr><td>waitIterateAll</td><td>输入</td><td>仅在异步场景下使用，是否需要通过WaitIterateAll接口等待IterateAll执行结束。 true：需要通过WaitIterateAll接口等待IterateAll执行结束。 false：不需要通过WaitIterateAll接口等待IterateAll执行结束，开发者自行处理等待IterateAll执行结束的过程。</td></tr><tr><td>fakeMsg</td><td>输入</td><td>仅在IBShare场景（模板参数中开启了doIBShareNorm开关）和IntraBlockPartSum场景（模板参数中开启了intraBlockPartSum开关）使用。 IBShare场景 该场景复用L1上相同的A矩阵或B矩阵数据，要求AIV分核调用IterateAll的次数必须匹配，此时需要调用IterateAll并设置fakeMsg为true，不执行真正的计算，仅用来保证IterateAll调用成对出现。默认值为false，表示执行真正的计算。 IntraBlockPartSum场景 用于分离模式下的Vector计算、Cube计算融合，实现多个AIV核的一次Matmul计算结果（baseM * baseN大小的矩阵分片）在L0C Buffer上累加。默认值为false，表示执行各AIV核的Matmul计算结果在L0C Buffer上累加。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>传入的C矩阵地址空间大小需要保证不小于singleCoreM * singleCoreN个元素。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>IterateAll接口的调用示例如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling);</span></span>
<span class="line"><span>mm.SetTensorA(gm_a);</span></span>
<span class="line"><span>mm.SetTensorB(gm_b);</span></span>
<span class="line"><span>if (tiling.isBias) {</span></span>
<span class="line"><span>    mm.SetBias(gmBias);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>mm.IterateAll(gm_c);    // 计算</span></span>
<span class="line"><span>mm.End();</span></span></code></pre></div>`,20)])])}const m=a(n,[["render",r]]);export{c as __pageData,m as default};
